// Width breakpoint below which the client-view portal switches to a mobile
// bottom-nav layout. 768px matches the common tablet-portrait threshold so
// phones and small tablets get the app-style layout; iPad landscape and up
// keep the desktop sidebar.
const CLIENT_VIEW_MOBILE_BREAKPOINT_PX = 768;

function useViewportIsMobile(breakpointPx) {
  const initial = typeof window !== "undefined"
    ? window.innerWidth <= breakpointPx
    : false;
  const [isMobile, setIsMobile] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const mq = window.matchMedia(`(max-width: ${breakpointPx}px)`);
    const handler = (e) => setIsMobile(e.matches);
    setIsMobile(mq.matches);
    if (mq.addEventListener) {
      mq.addEventListener("change", handler);
      return () => mq.removeEventListener("change", handler);
    }
    // Safari < 14
    mq.addListener(handler);
    return () => mq.removeListener(handler);
  }, [breakpointPx]);
  return isMobile;
}

// Max number of icons we show in the mobile bottom nav before collapsing the
// rest under a "More" sheet. 5 = 4 module icons + a sheet trigger, matching
// iOS / Android conventions.
const CLIENT_VIEW_MOBILE_NAV_MAX = 4;

function ClientMobileNav({ items, activePage, onPick, currentUser, onLogout }) {
  const [moreOpen, setMoreOpen] = useState(false);
  const visible = items.slice(0, CLIENT_VIEW_MOBILE_NAV_MAX);
  const overflow = items.slice(CLIENT_VIEW_MOBILE_NAV_MAX);
  const showMoreButton = overflow.length > 0 || true; // also doubles as user/logout entry

  return (
    <>
      <nav className="client-mobile-nav" role="navigation" aria-label="Customer portal">
        {visible.map((it) => {
          const active = activePage === it.page;
          return (
            <button
              key={`cmn-${it.page}`}
              type="button"
              className={`cmn-tab ${active ? "active" : ""}`}
              onClick={() => onPick(it.page)}
              aria-current={active ? "page" : undefined}
              aria-label={it.label}
            >
              <span className="cmn-tab-icon" aria-hidden="true">
                <MenuIcon page={it.page} />
              </span>
              <span className="cmn-tab-label">{it.label}</span>
            </button>
          );
        })}
        {showMoreButton ? (
          <button
            type="button"
            className={`cmn-tab cmn-tab-more ${moreOpen ? "active" : ""}`}
            onClick={() => setMoreOpen((v) => !v)}
            aria-haspopup="dialog"
            aria-expanded={moreOpen}
            aria-label="More menu"
          >
            <span className="cmn-tab-icon" aria-hidden="true">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                <circle cx="6" cy="12" r="2" /><circle cx="12" cy="12" r="2" /><circle cx="18" cy="12" r="2" />
              </svg>
            </span>
            <span className="cmn-tab-label">More</span>
          </button>
        ) : null}
      </nav>

      {moreOpen ? (
        <>
          <div
            className="cmn-sheet-scrim"
            onClick={() => setMoreOpen(false)}
            aria-hidden="true"
          />
          <div className="cmn-sheet" role="dialog" aria-label="More menu">
            <div className="cmn-sheet-handle" aria-hidden="true" />
            <div className="cmn-sheet-user">
              <div className="cmn-sheet-user-line user">{currentUser?.username || "—"}</div>
              <div className="cmn-sheet-user-line role">{currentUser?.role || ""}</div>
            </div>
            <div className="cmn-sheet-list">
              {overflow.map((it) => (
                <button
                  key={`cms-${it.page}`}
                  type="button"
                  className={`cmn-sheet-item ${activePage === it.page ? "active" : ""}`}
                  onClick={() => { onPick(it.page); setMoreOpen(false); }}
                >
                  <span className="cmn-sheet-icon" aria-hidden="true">
                    <MenuIcon page={it.page} />
                  </span>
                  <span>{it.label}</span>
                </button>
              ))}
            </div>
            <div className="cmn-sheet-footer">
              <button
                type="button"
                className="cmn-sheet-logout"
                onClick={() => { setMoreOpen(false); onLogout?.(); }}
              >
                Sign out
              </button>
            </div>
          </div>
        </>
      ) : null}
    </>
  );
}

// Portal Edge Apps row — Client View cell.
// Fetches (or mints) a per-edge read-only Lite share-link token. Renders
// three actions: Open (new tab), Copy URL, Rotate. Anyone with the URL
// can view the Lite app scoped to this edge without logging in.
function EdgeClientViewCell({ row, tenantScope }) {
  const edgeId = String(row?.edge_id || "").trim();
  const [link, setLink] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [justCopied, setJustCopied] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!edgeId) return;
      try {
        const res = await getEdgeViewLink(edgeId, tenantScope);
        if (cancelled) return;
        setLink(res?.link || null);
      } catch (e) {
        if (!cancelled) setError(String(e?.message || e));
      }
    })();
    return () => { cancelled = true; };
  }, [edgeId, tenantScope]);

  const ensureLink = async () => {
    if (link) return link;
    setBusy(true);
    setError("");
    try {
      const res = await createEdgeViewLink(edgeId, tenantScope);
      const next = res?.link || null;
      setLink(next);
      return next;
    } catch (e) {
      setError(String(e?.message || e));
      return null;
    } finally {
      setBusy(false);
    }
  };

  const onOpen = async () => {
    const lk = await ensureLink();
    if (!lk?.token) return;
    const url = buildEdgeViewLinkUrl(lk.token);
    try { window.open(url, "_blank", "noopener,noreferrer"); } catch (_) {}
  };

  const onCopy = async () => {
    const lk = await ensureLink();
    if (!lk?.token) return;
    const url = buildEdgeViewLinkUrl(lk.token);
    try {
      await navigator.clipboard.writeText(url);
      setJustCopied(true);
      setTimeout(() => setJustCopied(false), 1500);
    } catch (_) {
      // Fallback for environments without clipboard permission
      try {
        const ta = document.createElement("textarea");
        ta.value = url;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        setJustCopied(true);
        setTimeout(() => setJustCopied(false), 1500);
      } catch (_) {}
    }
  };

  const onRotate = async () => {
    if (!edgeId) return;
    if (!window.confirm("Rotate the Client View link?\n\nThe current URL stops working immediately and a new one is generated. Anyone with the old link will lose access.")) return;
    setBusy(true);
    setError("");
    try {
      const res = await rotateEdgeViewLink(edgeId, tenantScope);
      setLink(res?.link || null);
      setJustCopied(false);
    } catch (e) {
      setError(String(e?.message || e));
    } finally {
      setBusy(false);
    }
  };

  if (!edgeId) return <span>-</span>;
  return (
    <span style={{ display: "inline-flex", gap: 6, alignItems: "center" }}>
      <button
        type="button"
        className="btn btn-secondary btn-sm"
        onClick={onOpen}
        disabled={busy}
        title="Open the read-only Lite view in a new tab"
      >Open</button>
      <button
        type="button"
        className="btn btn-secondary btn-sm"
        onClick={onCopy}
        disabled={busy}
        title="Copy the shareable URL to clipboard"
      >{justCopied ? "Copied!" : "Copy"}</button>
      <button
        type="button"
        className="btn btn-danger btn-sm"
        onClick={onRotate}
        disabled={busy || !link}
        title="Invalidate the current link and mint a new one"
      >Rotate</button>
      {error ? <span style={{ color: "#d35454", fontSize: 11, marginLeft: 4 }} title={error}>!</span> : null}
    </span>
  );
}

// Per-user Lite share token. Renders Generate / Copy / Rotate on a Users
// table row so an admin can mint one local-LAN Lite URL per user. The
// Copy button puts a full http://<lan-ip>:<lan-port>/lite/?token=<...>
// URL on the clipboard so the user can paste it into any LAN browser.
// Falls back to copying just the token if LAN sharing is off.
function UserClientViewCell({ row, tenantScope, edgeId, isAdminViewer }) {
  const userId = String(row?.username || row?.user_id || "").trim();
  const [link, setLink] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [justCopied, setJustCopied] = useState(false);
  const [lanTargets, setLanTargets] = useState({ urls: [], running: false });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!userId || !edgeId) return;
      try {
        const [res, targets] = await Promise.all([
          getEdgeUserViewLink(edgeId, userId, tenantScope),
          getLiteLocalShareTargets(),
        ]);
        if (cancelled) return;
        setLink(res?.link || null);
        setLanTargets(targets || { urls: [], running: false });
      } catch (e) {
        if (!cancelled) setError(String(e?.message || e));
      }
    })();
    return () => { cancelled = true; };
  }, [userId, edgeId, tenantScope]);

  const ensureLink = async () => {
    if (link?.token) return link;
    setBusy(true);
    setError("");
    try {
      const res = await createEdgeUserViewLink(edgeId, userId, tenantScope);
      const next = res?.link || null;
      setLink(next);
      return next;
    } catch (e) {
      setError(String(e?.message || e));
      return null;
    } finally {
      setBusy(false);
    }
  };

  // Operator 2026-06-18: per-user LAN URL respects the user's
  // access_full / access_lite / access_client permission flags. If the
  // admin clicked plain Copy, we pick the highest variant the user is
  // allowed to open. The three explicit copy buttons below force a
  // specific variant (only enabled when the user has that access).
  const copyWithVariant = async (forced) => {
    const lk = await ensureLink();
    if (!lk?.token) return;
    const perms = row?.permissions || {};
    const variant = forced || pickLanVariantForUser(perms) || "lite";
    let textToCopy = lk.token;
    if (lanTargets?.urls?.length) {
      textToCopy = buildLanUrlForVariant(lanTargets.urls[0], lk.token, variant);
    }
    try {
      await navigator.clipboard.writeText(textToCopy);
      setJustCopied(true);
      setTimeout(() => setJustCopied(false), 1500);
    } catch (_) {
      try {
        const ta = document.createElement("textarea");
        ta.value = textToCopy;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        setJustCopied(true);
        setTimeout(() => setJustCopied(false), 1500);
      } catch (_) {}
    }
  };
  const onCopy = () => copyWithVariant(null);

  const onRotate = async () => {
    if (!userId || !edgeId) return;
    if (!window.confirm(`Rotate the Lite access link for '${userId}'?\n\nThe current URL stops working immediately and a new one is generated. The user must paste the new URL.`)) return;
    setBusy(true);
    setError("");
    try {
      const res = await rotateEdgeUserViewLink(edgeId, userId, tenantScope);
      setLink(res?.link || null);
      setJustCopied(false);
    } catch (e) {
      setError(String(e?.message || e));
    } finally {
      setBusy(false);
    }
  };

  if (!isAdminViewer) return <span style={{ color: "#666", fontSize: 11 }}>—</span>;
  if (!userId || !edgeId) return <span>-</span>;
  const perms = row?.permissions || {};
  const canFull = !!perms.access_full;
  const canLite = !!perms.access_lite;
  const canClient = !!perms.access_client;
  const hasAnyAccess = canFull || canLite || canClient;
  const variantBtn = (variant, label, enabled, title) => (
    <button
      key={variant}
      type="button"
      className="btn btn-secondary btn-sm"
      onClick={() => copyWithVariant(variant)}
      disabled={busy || !enabled}
      title={enabled ? title : `Grant '${label}' access on this user to enable`}
    >{label}</button>
  );
  return (
    <span style={{ display: "inline-flex", gap: 4, alignItems: "center", flexWrap: "wrap" }}>
      {!hasAnyAccess ? (
        <span style={{ color: "#777", fontSize: 11 }}>no access flags</span>
      ) : (
        <>
          {variantBtn("full", "Full",   canFull,   `Copy /trustnode/full/?token=… for ${userId}`)}
          {variantBtn("lite", "Lite",   canLite,   `Copy /trustnode/lite/?token=… for ${userId}`)}
          {variantBtn("client","Client",canClient, `Copy /trustnode/client/?token=… for ${userId}`)}
        </>
      )}
      <button
        type="button"
        className="btn btn-danger btn-sm"
        onClick={onRotate}
        disabled={busy || !link}
        title="Invalidate the current link and mint a new one"
      >Rotate</button>
      {justCopied ? <span style={{ color: "#5eead4", fontSize: 11, marginLeft: 2 }}>copied</span> : null}
      {error ? <span style={{ color: "#d35454", fontSize: 11, marginLeft: 4 }} title={error}>!</span> : null}
    </span>
  );
}

// ──────────────────────────────────────────────────────────────────────
// Connections pages (operator 2026-06-17, Phase 3). OPC UA / MQTT
// servers that the edge runs on the LAN so external SCADA / HMI
// clients can read TrustNode tags. Settings persist in
// app_settings.connections via /api/connections/*.
// ──────────────────────────────────────────────────────────────────────
function ConnectionsOverviewPage() {
  const [opc, setOpc] = useState({ running: false, port: 0 });
  const [mqtt, setMqtt] = useState({ running: false, port: 0 });
  useEffect(() => {
    let cancelled = false;
    const poll = async () => {
      try {
        const [o, m] = await Promise.all([getOpcuaStatus(), getMqttStatus()]);
        if (cancelled) return;
        setOpc(o || {});
        setMqtt(m || {});
      } catch (_) {}
    };
    poll();
    const t = setInterval(poll, 3000);
    return () => { cancelled = true; clearInterval(t); };
  }, []);
  return (
    <section className="card">
      <h3 style={{ marginTop: 0 }}>Outbound Connections</h3>
      <p className="muted" style={{ marginTop: 0 }}>Expose TrustNode tags to LAN clients over OPC UA or MQTT. Configure each in the sub-pages.</p>
      <div className="form-grid" style={{ gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 16, marginTop: 12 }}>
        <div className="card" style={{ padding: 14 }}>
          <h4 style={{ margin: 0 }}>OPC UA Server</h4>
          <div className="row" style={{ marginTop: 8, alignItems: "center", gap: 8 }}>
            <span className={`status-pill ${opc.running ? "status-online" : "status-offline"}`}>{opc.running ? "Running" : "Stopped"}</span>
            {opc.running ? <span className="muted">opc.tcp://&lt;edge-ip&gt;:{opc.port}/trustnode/edge</span> : null}
          </div>
          {opc.last_error ? <div className="lock-note" style={{ marginTop: 8 }}>Last error: {opc.last_error}</div> : null}
        </div>
        <div className="card" style={{ padding: 14 }}>
          <h4 style={{ margin: 0 }}>MQTT Broker</h4>
          <div className="row" style={{ marginTop: 8, alignItems: "center", gap: 8 }}>
            <span className={`status-pill ${mqtt.running ? "status-online" : "status-offline"}`}>{mqtt.running ? "Running" : "Stopped"}</span>
            {mqtt.running ? <span className="muted">tcp://&lt;edge-ip&gt;:{mqtt.port}</span> : null}
          </div>
          {mqtt.last_error ? <div className="lock-note" style={{ marginTop: 8 }}>Last error: {mqtt.last_error}</div> : null}
        </div>
      </div>
    </section>
  );
}

function OpcuaSettingsPage({ canEdit }) {
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState({ running: false, port: 4840, config: {} });
  const [form, setForm] = useState({
    port: 4840,
    server_name: "TrustNode Edge OPC UA",
    anonymous: true,
    username: "",
    password: "",
    runtime: "python",
  });
  const refresh = async () => {
    try {
      const s = await getOpcuaStatus();
      setStatus(s || {});
      if (s?.config) {
        setForm((f) => ({
          ...f,
          port: Number(s.config.port || f.port || 4840),
          server_name: String(s.config.server_name || f.server_name),
          anonymous: s.config.anonymous !== false,
          username: String(s.config.username || ""),
          password: String(s.config.password || ""),
          runtime: String(s.config.runtime || "python"),
        }));
      }
    } catch (_) {}
  };
  useEffect(() => { refresh(); }, []);
  const onEnable = async () => {
    setBusy(true);
    try {
      await setOpcuaEnabled({ enabled: true, ...form });
      await refresh();
    } finally { setBusy(false); }
  };
  const onDisable = async () => {
    setBusy(true);
    try {
      await setOpcuaDisabled();
      await refresh();
    } finally { setBusy(false); }
  };
  return (
    <section className="card">
      <h3 style={{ marginTop: 0 }}>OPC UA Server</h3>
      <p className="muted">Exposes tags flagged "Publish to OPC UA" on the Tags page. Endpoint <code>opc.tcp://&lt;edge-ip&gt;:{form.port}/trustnode/edge</code>.</p>
      <div className="row" style={{ alignItems: "center", gap: 10 }}>
        <span className={`status-pill ${status.running ? "status-online" : "status-offline"}`}>{status.running ? `Running on port ${status.port}` : "Stopped"}</span>
        {!status.running && canEdit ? <button className="btn btn-primary" disabled={busy} onClick={onEnable}>Turn ON</button> : null}
        {status.running && canEdit ? <button className="btn btn-danger" disabled={busy} onClick={onDisable}>Turn OFF</button> : null}
      </div>
      {status.last_error ? <div className="lock-note" style={{ marginTop: 10 }}>Last error: {status.last_error}</div> : null}
      <div className="form-grid" style={{ gridTemplateColumns: "repeat(2, minmax(0, 1fr))", marginTop: 14, gap: 12 }}>
        <label>Runtime
          <select value={form.runtime} onChange={(e) => setForm({ ...form, runtime: e.target.value })} disabled={!canEdit || status.running}>
            <option value="python">Python (asyncua) — bundled</option>
            <option value="native">OPC Foundation .NET — native sidecar</option>
          </select>
        </label>
        <label>Port<input type="number" value={form.port} onChange={(e) => setForm({ ...form, port: Number(e.target.value || 4840) })} disabled={!canEdit || status.running} /></label>
        <label>Server name<input value={form.server_name} onChange={(e) => setForm({ ...form, server_name: e.target.value })} disabled={!canEdit || status.running} /></label>
        <label className="remember-row" style={{ marginTop: 8 }}>
          <input type="checkbox" checked={form.anonymous} onChange={(e) => setForm({ ...form, anonymous: e.target.checked })} disabled={!canEdit || status.running} />
          <span>Allow anonymous (no login)</span>
        </label>
        {!form.anonymous ? <>
          <label>Username<input value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} disabled={!canEdit || status.running} /></label>
          <label>Password<input type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} disabled={!canEdit || status.running} /></label>
        </> : null}
      </div>
      {form.runtime === "native" ? (
        <div className="lock-note" style={{ marginTop: 12 }}>
          The OPC Foundation .NET sidecar is not bundled in this build. Selecting it will report "not installed" until the native runtime is dropped in <code>backend/sidecars/opcua/</code>.
        </div>
      ) : null}
    </section>
  );
}

