    const selected = String(prev?.selected_device_id || "");
    const nextSelected = selected === did ? String(devices[0]?.id || "") : selected;
    const nextConfig = { ...(prev || {}), devices, selected_device_id: nextSelected };
    setPowerConfig(nextConfig);
