  const saveCpLicenseModal = async () => {
    if (!canEditPage("control_plane")) return;
    const customerId = String(cpLicenseForm.customer_id || "").trim();
    if (!customerId) {
      setCpModalError("Select a customer for this license.");
      return;
    }
    const startDate = String(cpLicenseForm.start_utc || "").trim();
    const endDate = String(cpLicenseForm.end_utc || "").trim();
    if (startDate && Number.isNaN(Date.parse(`${startDate}T00:00:00Z`))) {
      setCpModalError("Start date format is invalid.");
      return;
    }
    if (endDate && Number.isNaN(Date.parse(`${endDate}T00:00:00Z`))) {
      setCpModalError("End date format is invalid.");
      return;
    }
    if (startDate && endDate && Date.parse(`${endDate}T00:00:00Z`) < Date.parse(`${startDate}T00:00:00Z`)) {
      setCpModalError("End date must be later than start date.");
      return;
    }
    setCpModalError("");
    setCpBusy(true);
    try {
      const payload = {
        license_id: String(cpLicenseForm.license_id || "").trim(),
        customer_id: customerId,
        plan_code: String(cpLicenseForm.plan_code || "standard").trim() || "standard",
        status: String(cpLicenseForm.status || "active").trim() || "active",
        start_utc: toUtcStartOfDay(startDate),
        end_utc: toUtcEndOfDay(endDate),
        max_edges: Math.max(1, Number(cpLicenseForm.max_edges || 1)),
        max_users: Math.max(1, Number(cpLicenseForm.max_users || 1)),
        metadata: {},
      };
      const scopedTenant = getControlPlaneTenantScope();
      const res = await upsertControlPlaneLicense(payload, scopedTenant);
      const finalLicenseId = String(res?.row?.license_id || payload.license_id || "").trim();
      if (finalLicenseId) {
        await setControlPlaneLicenseModules(finalLicenseId, {
          modules: (cpLicenseModalModules || []).map((m) => ({
            module_key: String(m?.module_key || ""),
            enabled: Boolean(m?.enabled),
          })),
        });
      }
      await refreshControlPlaneData(getControlPlaneTenantScope());
      setCpResult(`License '${finalLicenseId || payload.plan_code}' saved.`);
      setCpModalError("");
      setShowCpLicenseModal(false);
    } catch (err) {
      setCpModalError(`License save failed: ${String(err?.message || err)}`);
    } finally {
      setCpBusy(false);
    }
  };

